 function navigate(destination:string,back=false){Keyboard.dismiss();setNotice('');if(destination!==tab&&!back)navigationStack.current.push(tab);if(destination===tab){scrollPositions.current[destination]=0;scrollRef.current?.scrollTo({y:0,animated:true});return;}headerScroll.setValue(scrollPositions.current[destination]??0);setTab(destination);requestAnimationFrame(()=>scrollRef.current?.scrollTo({y:scrollPositions.current[destination]??0,animated:false}));}
