 if(!data)return <SafeAreaView style={s.center}>{error?<><Text style={s.title}>{error}</Text><Button title="Retry loading" onPress={()=>{setError('');loadData().then(setData).catch(e=>setError(e.message));}}/></>:<ActivityIndicator color={c.accent}/>}</SafeAreaView>;
 function exitDemo(){setDemo(false);if(realData.current)setData(realData.current);setNotice('');navigate('Home');if(Platform.OS==='web')window.history.replaceState(null,'',window.location.pathname);}
