 function saveExercise(){if(editor?.videoUrl?.trim()&&!validVideoUrl(editor.videoUrl.trim())){setNotice('Enter a valid HTTPS video link.');return;}if(!editor?.name?.trim() || !Number.isInteger(editor.sets)||!Number.isInteger(editor.reps)||editor.sets!<1||editor.sets!>20||editor.reps!<1||editor.reps!>100){Alert.alert('Check exercise','Enter a name, 1–20 sets, and 1–100 reps.');setNotice('Enter a name, 1–20 sets, and 1–100 reps.');return;}const e={...editor,id:editor.id??uid(),name:editor.name.trim(),videoUrl:editor.videoUrl?.trim()||undefined} as Exercise;commit({...data!,exercises:editing?data!.exercises.map(x=>x.id===e.id?e:x):[...data!.exercises,e]});setEditor(undefined);}
 function move(id:string,delta:number){const list=[...data!.exercises];const i=list.findIndex(e=>e.id===id);const matches=list.map((e,j)=>e.category===list[i].category?j:-1).filter(j=>j>=0);const target=matches[matches.indexOf(i)+delta];if(target===undefined)return;[list[i],list[target]]=[list[target],list[i]];commit({...data!,exercises:list});}
 const sessions=data.sessions;const weekStart=new Date();weekStart.setHours(0,0,0,0);weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const weekly=sessions.filter(x=>new Date(x.started)>=weekStart);
